#include "stdafx.h"#define __MAIN_FILE__#include "ServerEx.h"#include "TrendReaderV0.h"#include <conio.h>#include <iostream>#include "resource.h"#include <CommProc.h>#include "ServerThreadPipe.h"#include "LogFile.h"const int INPBUFSIZE = 32768;const int OUTBUFSIZE = 32768;const int PIPE_TIMEOUT = 100;//==========================HANDLE		m_hServiceThread;CTrendReader m_trendReader;SECURITY_ATTRIBUTES sa;void MyErrExit(LPTSTR str)  {	fprintf(stderr, "%s", str);	exit(-1);  }static BOOL g_bStop;VOID InstanceThread(LPVOID lpvParam)   {  // The thread's parameter is a handle to a pipe instance.   KServerThreadPipe sThread( (HANDLE) lpvParam);  sThread.Run();   } DWORD WINAPI ServiceFunc( LPVOID lpParam ){  HANDLE hPipe, hThread;   BOOL fConnected;   DWORD dwThreadId;   //read Lamp tables into global map:	LPCTSTR ss = (LPCTSTR) lpParam;        // pipe name     for (;!g_bStop;)    {    hPipe = CreateNamedPipe(                       (LPCTSTR) lpParam,        // pipe name                         PIPE_ACCESS_DUPLEX,    		// read/write access                          PIPE_TYPE_MESSAGE |    		// message type pipe                       PIPE_READMODE_MESSAGE |		// message-read mode                       PIPE_WAIT,                // blocking mode                       PIPE_UNLIMITED_INSTANCES, // max. instances                        INPBUFSIZE,					        // output buffer size                       OUTBUFSIZE,                      // input buffer size                       PIPE_TIMEOUT,             // client time-out                       &sa);                     // security attribute     if (hPipe == INVALID_HANDLE_VALUE)           MyErrExit("CreatePipe");      // Wait for the client to connect; if it succeeds,      // the function returns a nonzero value. If the function returns      // zero, GetLastError returns ERROR_PIPE_CONNECTED.      fConnected = ConnectNamedPipe(hPipe, NULL) ?         TRUE : (GetLastError() == ERROR_PIPE_CONNECTED);      if (fConnected)       {       // Create a thread for this client.          hThread = CreateThread(             NULL,              // no security attribute             0,                 // default stack size             (LPTHREAD_START_ROUTINE) InstanceThread,             (LPVOID) hPipe,    // thread parameter             0,                 // not suspended             &dwThreadId);      // returns thread ID 				//DWORD Res = SetThreadIdealProcessor( hThread, 0 );         if (hThread == NULL)             MyErrExit("CreateThread");          else            CloseHandle(hThread);       }       else         // The client could not connect, so close the pipe.          CloseHandle(hPipe);    }   return 0;}void StartService(void)  {	g_bStop	= false;	m_hServiceThread	= NULL;  static char szPipeName[256];  sprintf_s( szPipeName, sizeof(szPipeName), _T("\\\\.\\pipe\\%s"), NAME_PIPE_SERVER );	DWORD dwThreadId;	m_hServiceThread = CreateThread( NULL, 0, ServiceFunc, (LPVOID)szPipeName, 0, &dwThreadId);//	DWORD Res = SetThreadIdealProcessor( m_hServiceThread, 0 );  //SetThreadAffinityMask( m_hServiceThread, 1 );	if ( m_hServiceThread != NULL )	  {		cout <<"Service started OK." << endl;	  }	else	  {		cout <<"Starting the Service failed for some reason." << endl;	  }  }void StopService(void)  {	g_bStop = TRUE;  }void MyStart()  {  CLogFile::Initialize ("ServerEx", TRUE, FALSE, "ServerEx.txt");  CLogFile::Log ("Starting ServerEx...");  SECURITY_DESCRIPTOR* psd;  psd = (SECURITY_DESCRIPTOR*) LocalAlloc(LPTR, SECURITY_DESCRIPTOR_MIN_LENGTH);  InitializeSecurityDescriptor(psd, SECURITY_DESCRIPTOR_REVISION);  SetSecurityDescriptorDacl(psd, TRUE, NULL, FALSE);  sa.nLength = sizeof(sa);  sa.lpSecurityDescriptor = psd;  sa.bInheritHandle = TRUE;  //# 1. START TRENDSERVICE  m_trendReader.StartServer();  StartService();  }void MyStop()  {  //# 4. STOP TRENDSERVICE  m_trendReader.StopServer();  if (m_hServiceThread)  StopService();  Sleep(1000);  }